WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='CARTILLA_ELECTROTECNIA' AND v.numero=1),d(t,o) AS (VALUES('Manipulador Tracción / Freno',1),('Motor de Tracción',2),('RELACIÓN DE ANOMALÍAS CORREGIDAS DURANTE LA REVISIÓN',3),('RELACIÓN DE OPERACIONES PENDIENTES',4),('PERSONAL',5)) INSERT INTO cartillas.secciones(version_id,titulo,orden) SELECT v.id,d.t,d.o FROM v CROSS JOIN d ON CONFLICT(version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='CARTILLA_ELECTROTECNIA' AND v.numero=1),s AS (SELECT id,titulo FROM cartillas.secciones WHERE version_id=(SELECT id FROM v)),d(t,c,e,ty,o,cf) AS (VALUES('Manipulador Tracción / Freno','manipulador','Manipulador Tracción / Freno','tabla',1,'{"columnas":[{"codigo":"tecnico","etiqueta":"TEC."},{"codigo":"manual","etiqueta":"MANUAL"},{"codigo":"descripcion","etiqueta":"DESCRIPCIÓN DE ACTIVIDADES"},{"codigo":"ma1","etiqueta":"Ma1"},{"codigo":"mb1","etiqueta":"Mb1"},{"codigo":"mb3","etiqueta":"Mb3"},{"codigo":"r","etiqueta":"R"},{"codigo":"mb2","etiqueta":"Mb2"},{"codigo":"ma2","etiqueta":"Ma2"},{"codigo":"observaciones","etiqueta":"OBSERVACIONES"}],"filasIniciales":[{"manual":"14.013","descripcion":"Desmontaje del manipulador (*)","condicion":"Deshabilitado y líneas desenergizado"},{"manual":"14.012","descripcion":"Revisión general (*)","condicion":"Deshabilitado y líneas desenergizado"},{"manual":"-","descripcion":"Procedimiento de pruebas en el manipulador (*)"},{"manual":"14.013","descripcion":"Montaje del manipulador (*)","condicion":"Deshabilitado y líneas desenergizado"}]}'),('Motor de Tracción','motor_traccion','Motor de Tracción','tabla',1,'{"columnas":[{"codigo":"tecnico","etiqueta":"TEC."},{"codigo":"manual","etiqueta":"MANUAL"},{"codigo":"descripcion","etiqueta":"DESCRIPCIÓN DE ACTIVIDADES"},{"codigo":"ma1","etiqueta":"Ma1"},{"codigo":"mb1","etiqueta":"Mb1"},{"codigo":"mb3","etiqueta":"Mb3"},{"codigo":"r","etiqueta":"R"},{"codigo":"mb2","etiqueta":"Mb2"},{"codigo":"ma2","etiqueta":"Ma2"},{"codigo":"observaciones","etiqueta":"OBSERVACIONES"}],"filasIniciales":[{"manual":"14.001","descripcion":"Desmontaje del motor de tracción (*)"},{"manual":"14.001","descripcion":"Revisión general (*)"},{"manual":"-","descripcion":"Procedimiento de pruebas (*)"},{"manual":"14.001","descripcion":"Montaje del motor de tracción (*)"}]}'),('RELACIÓN DE ANOMALÍAS CORREGIDAS DURANTE LA REVISIÓN','anomalias','RELACIÓN DE ANOMALÍAS CORREGIDAS DURANTE LA REVISIÓN','tabla',1,'{"columnas":[{"codigo":"equipo","etiqueta":"Equipo"},{"codigo":"ubicacion","etiqueta":"Ubicación"},{"codigo":"reparaciones","etiqueta":"Reparaciones efectuadas"},{"codigo":"inspeccion","etiqueta":"INS-BAJO BASTIDOR"}],"filasIniciales":[{},{},{},{},{},{},{},{}]}'),('RELACIÓN DE OPERACIONES PENDIENTES','pendientes','RELACIÓN DE OPERACIONES PENDIENTES','tabla',1,'{"columnas":[{"codigo":"equipo","etiqueta":"Equipo"},{"codigo":"ubicacion","etiqueta":"Ubicación"},{"codigo":"operaciones","etiqueta":"Operaciones pendientes"}],"filasIniciales":[{},{},{},{},{},{}]}'),('PERSONAL','personal_participo','Personal que participó en el mantenimiento:','texto',1,'{"multilinea":true}'),('PERSONAL','responsable_unna','RESPONSABLE UNNA:','texto',2,'{}'),('PERSONAL','firma_responsable_unna','FIRMA:','firma',3,'{}'),('PERSONAL','responsable','RESPONSABLE:','texto',4,'{}'),('PERSONAL','firma_responsable','FIRMA:','firma',5,'{}')) INSERT INTO cartillas.campos(seccion_id,codigo,etiqueta,tipo,orden,configuracion) SELECT s.id,d.c,d.e,d.ty,d.o,d.cf::jsonb FROM d JOIN s ON s.titulo=d.t ON CONFLICT(seccion_id,codigo) DO UPDATE SET configuracion=EXCLUDED.configuracion,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
